/// <summary>The field the hunters follow, searched again only when the wick has moved.</summary>
private void RefreshField()
{
    if (Wick.Cell != _fieldFrom)
    {
        _field = Search(Wick.Cell);
        _fieldFrom = Wick.Cell;
    }
}
